---@class WorldBossEntityMgr
---@field GetInstance fun(self:WorldBossEntityMgr):WorldBossEntityMgr
local WorldBossEntityMgr = Class("WorldBossEntityMgr", Singleton)

function WorldBossEntityMgr:__init()
    ---@type OverseaWorldBossComponent
    self._overseaWorldBossComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.OverseaWorldBossComponent)
end

function WorldBossEntityMgr:__delete()
    GameUtils.RemoveEntityCompByType(ECSComponentType.Constants.OverseaWorldBossComponent, self._overseaWorldBossComponent)
end

--region public dojo
function WorldBossEntityMgr:RequestWorldBossInfoDojo()
    GameUtils.Request(Interfaces.WorldBossInit, {}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            Events.Broadcast("EVENT_RequestWorldBossInfoDojo")
            return
        end
        local jsonData = response.data
        ---@type WorldBossInfoDojo
        local worldBossInfoDojo = self._overseaWorldBossComponent:GetWorldBossInfoDojo()
        worldBossInfoDojo:Fill(jsonData.worldBossInfo)
        local worldBossInitDojo = self._overseaWorldBossComponent:GetWorldBossInitDojo()
        worldBossInitDojo:Fill(jsonData.worldBossInfo)
        ---@type WorldBossPlanVo
        local scheduleVo = WorldBossUtils.GetWorldBossPlanVoById(worldBossInfoDojo.worldBossScheduleId)
        if scheduleVo then
            worldBossInfoDojo.startDay = scheduleVo.startDay
            worldBossInfoDojo.endDay = scheduleVo.endDay
            worldBossInfoDojo.range = scheduleVo.range
            worldBossInfoDojo.modelId = scheduleVo.modelId
            worldBossInfoDojo.NextID = scheduleVo.NextID
            worldBossInfoDojo.sceneId = scheduleVo.sceneId
        end

        worldBossInfoDojo.durationTime = WorldBossUtils.GetDurationTime(worldBossInfoDojo.startDay, worldBossInfoDojo.endDay)
        --worldBossInfoDojo.remainTime = -50.0 --18060.0

        worldBossInfoDojo:StartTimeDown()
        Events.Broadcast("EVENT_RequestWorldBossInfoDojo")
    end)
end

function WorldBossEntityMgr:RequestWorldBossHome(cb)
    GameUtils.Request(Interfaces.WorldBossHome, {}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            if cb then
                cb(nil)
            end
            Events.Broadcast(Constants.EventNames.OverseaWorldBossHomeReq)
            return
        end
        local jsonData = response.data
        self._overseaWorldBossComponent:SetHomeData(jsonData)
        if cb then
            cb(jsonData.playerRank)
        end
        Events.Broadcast(Constants.EventNames.OverseaWorldBossHomeReq)
    end)
end

function WorldBossEntityMgr:RequestWorldBossHurtRankList(cb)
    GameUtils.Request(Interfaces.WorldBossRank, {}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            Events.Broadcast("EVENT_RequestWorldBossHurtRankList", {}, 0)
            return
        end
        local jsonData = response.data
        local playerRank = checkTable(jsonData.playerRank)
        local rankInfoDojoList = {}
        for i, item in ipairs(jsonData.rankInfo) do
            ---@type RankingListDojo
            local dojo = RankingListDojo.New()
            dojo.rankNum = checkNumber(i)
            dojo:Fill(item)
            table.insert(rankInfoDojoList, dojo)
        end

        --table.sort(rankInfoDojoList, function(a, b)
        --    return a.score > b.score
        --end)
        if cb then
            cb(playerRank)
        end

        Events.Broadcast("EVENT_RequestWorldBossHurtRankList", rankInfoDojoList, checkNumber(jsonData.percentageRank))
    end)
end

function WorldBossEntityMgr:ReloadHistoryMaxHurt(cb)
    GameUtils.Request(Interfaces.WorldBossInit, {}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        local jsonData = response.data
        self._overseaWorldBossComponent:SetHistoryMaxHurt(checkNumber(jsonData.worldBossInfo.historyMaxHurt))
        if cb then
            cb()
        end
    end)
end

function WorldBossEntityMgr:WorldBossOneKeyDrawDrawRewardReq()
    GameUtils.Request(Interfaces.WorldBossdrawHurtReward, {}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        local jsonData = response.data
        local rewards = jsonData.rewards

        self._overseaWorldBossComponent:GetWorldBossInitDojo():OneKeyDraw()

        if #rewards > 0 then
            GoodsUtils.DrawRewards(rewards)
            UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = rewards } })
        end

        Events.Broadcast(Constants.EventNames.OverseaWorldBossOneKeyDrawRewardsReq)
    end)
end

function WorldBossEntityMgr:WorldBossDrawRewardReq(rewardId)
    GameUtils.Request(Interfaces.WorldBossdrawHurtReward, {rewardId = rewardId}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        local jsonData = response.data
        local rewards = jsonData.rewards

        self._overseaWorldBossComponent:GetWorldBossInitDojo():AddDrawId(rewardId)

        if #rewards > 0 then
            GoodsUtils.DrawRewards(rewards)
            UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = rewards } })
        end

        Events.Broadcast(Constants.EventNames.OverseaWorldBossDrawRewardsReq)
    end)
end

function WorldBossEntityMgr:RequestRewardInfo()
    GameUtils.Request(Interfaces.WorldBossInit, {}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        local jsonData = response.data
        local bossInitDojo = self._overseaWorldBossComponent:GetWorldBossInitDojo()
        bossInitDojo:Fill(jsonData.worldBossInfo)
        Events.Broadcast(Constants.EventNames.OverseaWorldBossInitReq)
    end)
end

