function WorldBossEntityMgr:LoadHurtRankRewards()
    local rankRewards = {}
    local t = CfUtils.GetCfTable(AutoIds.IdSetting976)
    if not t then
        return
    end
    for k, v in pairs(t) do
        ---@type WorldBossHurtRewardVo
        local vo = WorldBossHurtRewardVo.New()
        vo:FillVo(v)
        table.insert(rankRewards, vo)
    end
    return rankRewards
end

