--region public
function WorldBossEntityMgr:IsCanDrawReward()
    ---判断玩家当前能领取的总奖励中是否存在未领取过的奖励
    local allCanDrawRewards = self:GetAllCanDrawItems()
    for i, vo in pairs(allCanDrawRewards) do
        local drawFlag = self._overseaWorldBossComponent:IsRewardDraw(vo.id)
        if not drawFlag then
            --- 未领取
            return true
        end
    end
    --- 所有奖励都被领取
    return false
end
--endregion public

--region private

function WorldBossEntityMgr:GetAllCanDrawItems()
    local allRewards = self:LoadHurtRankRewards()
    local historyMaxHurt = self._overseaWorldBossComponent:GetHistoryMaxHurt()
    local allCanDrawRewards = {}
    for i, v in pairs(allRewards) do
        ---@type WorldBossHurtRewardVo
        local vo = v
        if historyMaxHurt >= vo.upperLimit then
            table.insert(allCanDrawRewards, vo)
        end
    end
    return allCanDrawRewards
end

---SetAllRewardsIsDrawn 将所有可领取的奖励设置为已领取状态
function WorldBossEntityMgr:SetAllRewardsIsDrawn()
    local allCanDrawRewards = self:GetAllCanDrawItems()
    for i, vo in pairs(allCanDrawRewards) do
        local drawFlag = self._overseaWorldBossComponent:IsRewardDraw(vo.id)
        if not drawFlag then
            --- 未领取
            self._overseaWorldBossComponent:SetHurtDrawRewardIdById(vo.id)
        end
    end
end
--endregion private

return WorldBossEntityMgr